                    <ul>
                        <li>Agencias de publicidad, relaciones públicas y comunicación</li>
                        <li>Marketing digital, redes sociales y e-commerce</li>
                        <li>Brand management en empresas medianas, grandes y multinacionales</li>
                        <li>Investigación de mercados y análisis del consumidor</li>
                        <li>Consultoría comercial y estratégica</li>
                        <li>Planeación de medios y experiencia de usuario</li>
                    </ul>
                </div>
                <div class="content-box">
                    <h4 style="color: var(--doc);">Perfil de ingreso ideal</h4>
                    <ul>
                        <li>Pensamiento analítico combinado con creatividad</li>
                        <li>Interés en el comportamiento del consumidor</li>
                        <li>Afinidad por la tecnología y las redes sociales</li>
                        <li>Habilidades de comunicación y persuasión</li>
                        <li>Bachillerato terminado (cualquier área)</li>
                    </ul>
                </div>
            </div>

            <div class="faq-wrap">
                <h3 class="faq-title">Preguntas frecuentes</h3>
                <details>
                    <summary>
                        ¿En qué se diferencia la Licenciatura en Mercadotecnia de la UIC de otras universidades?
                    </summary>
                    <div class="faq-ans">
                        <p>
                            La diferencia principal es que
                            forma mercadólogos capaces de tomar decisiones creativas basadas en
                            números, no solo creadores de contenido o campañas. Nuestro programa
                            destaca porque:
                        </p>
                        <ul class="lista-fa">
                            <li>Logra un equilibrio estratégico entre la analítica numérica y el desarrollo creativo.</li>
                            <li>Te conecta con el mundo laboral desde los primeros semestres trabajando con pymes y empresas reconocidas.</li>
                            <li>Garantiza la aplicación directa de conceptos frente a retos empresariales auténticos.</li>
                        </ul>
                    </div>
                </details>
                <details>
                    <summary>
                        ¿Un mercadólogo necesita saber programar o ser muy matemático?
                    </summary>
                    <div class="faq-ans">
                        <p>
                            No necesariamente. El objetivo no es
                            formarte como analista de datos o programador, sino como un estratega capaz
                            de interpretar y utilizar los datos a tu favor. En la UIC desarrollarás habilidades para:
                        </p>
                        <ul class="lista-fa">
                            <li>Integrar la estadística y la analítica de datos de forma 100% aplicada.</li>
                            <li>Leer métricas y tomar decisiones de negocio respaldadas por Big Data.</li>
                            <li>Comunicar resultados estratégicamente a clientes y mesas directivas.</li>
                        </ul>
                    </div>
                </details>
                <details>
                    <summary>
                        ¿A quién le conviene estudiar Mercadotecnia en la UIC?
                    </summary>
                    <div class="faq-ans">
                        <p>
                            Es ideal para personas que buscan combinar
                            el pensamiento analítico con el creativo para dominar el comportamiento del
                            consumidor. Te conviene estudiar aquí si te apasiona:
                        </p>
                        <ul class="lista-fa">
                            <li>Manejar redes sociales para el posicionamiento real de la marca (más allá de solo generar contenido).</li>
                            <li>Idear, diseñar y lanzar nuevos productos y servicios al mercado.</li>
                            <li>Desarrollarte en áreas de alto impacto como relaciones públicas, organización de eventos o dirección de ventas.</li>
                        </ul>
                    </div>
                </details>
            </div>
        </div>
    </section>

